// На 06.10 MP3 нет ни в одной из молитв ниже (тестовые записи удалены). Загрузит клиент — заменить молитву, это не баг.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Молитва по шагам', () => {
  test('GP-08 Нет записи: «אין הקראה לקטע הזה», «השמע» неактивна #a5decf4a @prod-safe @mobile', async ({ page }) => {
    for (const key of ['mincha_sfarad', 'shacharit_ashkenaz', 'arvit_ashkenaz']) {
      await page.goto(`/prayer/${key}`);
      await expect(page.getByText('האזן להקראה', { exact: true }), key).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('אין הקראה לקטע הזה'), key).toBeVisible();
      await expect(page.getByRole('button', { name: 'השמע' }), key).toBeDisabled();
    }
  });
});
